#!/bin/bash ################################# # CONFIGURATION ################################# USER="sdpuser" BASE_PATH="/var/opt/fds/config/ere" REFERENCE_SDP="SDP27B" CONFIG_FILE="sdp.config" MAX_PARALLEL=20 # Number of parallel SSH connections # Trees that are allowed to have only 1 file (won't alarm for 1, but will alarm for 0) IGNORE_SINGLE_FILE_TREES=("Statistic" "PreAnalysis") # Categories that are allowed to have only 1 file (won't alarm for 1, but will alarm for 0) # Format: "TreeName:Category" IGNORE_SINGLE_FILE_CATEGORIES=("ProductFee:main" "Bonus:special") # Output files TS=$(date +%Y%m%d_%H%M%S) RAW_DATA="ere_raw_${TS}.tmp" FILE_DATA="ere_files_${TS}.tmp" ALARM_FILE="sdp_alarms_${TS}.txt" STATS_FILE="sdp_stats_${TS}.txt" > "$RAW_DATA" > "$FILE_DATA" > "$ALARM_FILE" > "$STATS_FILE" ################################# # COLLECT FROM REFERENCE SDP ################################# echo "Collecting from reference: $REFERENCE_SDP" ssh -n -T -o ConnectTimeout=10 -o LogLevel=ERROR "${USER}@${REFERENCE_SDP}" \ "bash -c 'for t in $BASE_PATH/*; do [ -d \"\$t\" ] || continue; name=\$(basename \"\$t\"); [ ! -d \"\$t/active\" ] && continue; count=\$(ls -1 \"\$t/active\"/*.cfg 2>/dev/null | grep -v \"\.bak$\" | wc -l); echo \"REF \$name \$count\"; for f in \"\$t/active\"/*; do [ -f \"\$f\" ] || continue; fname=\$(basename \"\$f\"); [[ \"\$fname\" == *.bak ]] && continue; cat=\"\${fname%%_*}\"; echo \"FILE \$name \$cat \$fname REFERENCE\"; done; done'" \ 2>/dev/null > "${RAW_DATA}.ref" grep "^REF " "${RAW_DATA}.ref" > "$RAW_DATA" grep "^FILE " "${RAW_DATA}.ref" > "$FILE_DATA" rm -f "${RAW_DATA}.ref" if [ ! -s "$RAW_DATA" ]; then echo "ERROR: Failed to collect from reference SDP" exit 1 fi TREES=$(grep "^REF " "$RAW_DATA" | awk '{print $2}') TREE_COUNT=$(echo "$TREES" | wc -w) echo "Found $TREE_COUNT trees on reference" ################################# # READ CONFIG INTO ARRAYS ################################# declare -a SDP_IPS declare -a SDP_HOSTS while IFS=',' read -r ip hostname; do hostname=$(echo "$hostname" | tr -d '\r' | xargs) ip=$(echo "$ip" | tr -d '\r' | xargs) [[ "$hostname" =~ ^[Hh]ostname$ ]] && continue [ -z "$hostname" ] && continue SDP_IPS+=("$ip") SDP_HOSTS+=("$hostname") done < "$CONFIG_FILE" TOTAL_SDPS=${#SDP_HOSTS[@]} echo "Total SDPs to check: $TOTAL_SDPS" echo "Collecting data in parallel (max $MAX_PARALLEL at once)..." echo "" ################################# # COLLECT FROM ALL SDPs IN PARALLEL ################################# # Temp directory for parallel results TEMP_DIR=$(mktemp -d) # Function to collect from one SDP collect_sdp() { local idx=$1 local hostname="${SDP_HOSTS[$idx]}" local ip="${SDP_IPS[$idx]}" local output_file="$TEMP_DIR/${hostname}.out" # Single SSH call collects everything (excluding .bak files) if ssh -n -T -o ConnectTimeout=10 -o LogLevel=ERROR "${USER}@${ip}" \ "bash -c 'for t in $BASE_PATH/*; do [ -d \"\$t\" ] || continue; name=\$(basename \"\$t\"); [ ! -d \"\$t/active\" ] && continue; count=\$(ls -1 \"\$t/active\"/*.cfg 2>/dev/null | grep -v \"\.bak$\" | wc -l); echo \"NODE \$name \$count $hostname\"; for f in \"\$t/active\"/*; do [ -f \"\$f\" ] || continue; fname=\$(basename \"\$f\"); [[ \"\$fname\" == *.bak ]] && continue; cat=\"\${fname%%_*}\"; echo \"FILE \$name \$cat \$fname $hostname\"; done; done'" \ > "$output_file" 2>/dev/null; then echo "SUCCESS" > "${output_file}.status" else echo "FAILED" > "${output_file}.status" fi } # Export function and variables for parallel execution export -f collect_sdp export USER BASE_PATH export SDP_HOSTS SDP_IPS TEMP_DIR # Run collections in parallel batches RUNNING=0 for idx in "${!SDP_HOSTS[@]}"; do hostname="${SDP_HOSTS[$idx]}" echo "[$((idx + 1))/$TOTAL_SDPS] Starting $hostname..." # Run in background collect_sdp "$idx" & ((RUNNING++)) # If we hit max parallel, wait for some to finish if [ $RUNNING -ge $MAX_PARALLEL ]; then wait -n # Wait for any one job to finish ((RUNNING--)) fi done # Wait for all remaining jobs echo "Waiting for remaining collections to complete..." wait echo "" echo "Merging results..." # Collect all results SUCCESSFUL=0 for idx in "${!SDP_HOSTS[@]}"; do hostname="${SDP_HOSTS[$idx]}" output_file="$TEMP_DIR/${hostname}.out" status_file="${output_file}.status" if [ -f "$status_file" ] && [ "$(cat "$status_file")" = "SUCCESS" ]; then cat "$output_file" | grep "^NODE " >> "$RAW_DATA" cat "$output_file" | grep "^FILE " >> "$FILE_DATA" ((SUCCESSFUL++)) else echo "[ALARM] $hostname - SSH failed or no output" >> "$ALARM_FILE" fi done # Cleanup temp directory rm -rf "$TEMP_DIR" echo "Collected from $SUCCESSFUL/$TOTAL_SDPS SDPs" echo "" ################################# # CHECK MISSING TREES ################################# echo "Checking for missing trees..." # Group missing trees by tree name declare -A missing_tree_sdps # tree -> list of SDPs missing it for tree in $TREES; do for idx in "${!SDP_HOSTS[@]}"; do hostname="${SDP_HOSTS[$idx]}" if ! grep -q "^NODE $tree .* $hostname$" "$RAW_DATA"; then if [ -z "${missing_tree_sdps[$tree]}" ]; then missing_tree_sdps[$tree]="$hostname" else missing_tree_sdps[$tree]="${missing_tree_sdps[$tree]},$hostname" fi fi done done # Write grouped alarms for tree in "${!missing_tree_sdps[@]}"; do sdp_list="${missing_tree_sdps[$tree]}" sdp_count=$(echo "$sdp_list" | tr ',' '\n' | wc -l) if [ "$sdp_count" -eq 1 ]; then echo "[ALARM] $sdp_list - missing tree [$tree]" >> "$ALARM_FILE" elif [ "$sdp_count" -eq "$TOTAL_SDPS" ]; then echo "[ALARM] All $TOTAL_SDPS SDPs - missing tree [$tree]" >> "$ALARM_FILE" else echo "[ALARM] $sdp_count SDPs - missing tree [$tree]" >> "$ALARM_FILE" echo " Affected: $sdp_list" >> "$ALARM_FILE" fi done ################################# # CHECK CATEGORY FILE COUNTS ################################# echo "Checking category file counts..." # Helper function to check if tree is whitelisted is_tree_whitelisted() { local tree=$1 for wl_tree in "${IGNORE_SINGLE_FILE_TREES[@]}"; do [ "$tree" = "$wl_tree" ] && return 0 done return 1 } # Helper function to check if category is whitelisted is_category_whitelisted() { local tree=$1 local category=$2 local combo="${tree}:${category}" for wl_cat in "${IGNORE_SINGLE_FILE_CATEGORIES[@]}"; do [ "$combo" = "$wl_cat" ] && return 0 done return 1 } # Collect all file count issues first, then group them declare -A zero_file_issues # tree:category -> list of SDPs declare -A one_file_issues # tree:category -> list of SDPs for tree in $TREES; do REF_CATEGORIES=$(grep "^FILE $tree .* REFERENCE$" "$FILE_DATA" | awk '{print $3}' | sort -u) for category in $REF_CATEGORIES; do for idx in "${!SDP_HOSTS[@]}"; do hostname="${SDP_HOSTS[$idx]}" grep -q "^NODE $tree .* $hostname$" "$RAW_DATA" || continue file_count=$(grep "^FILE $tree $category .* $hostname$" "$FILE_DATA" | wc -l) key="${tree}:${category}" if [ "$file_count" -eq 0 ]; then if [ -z "${zero_file_issues[$key]}" ]; then zero_file_issues[$key]="$hostname" else zero_file_issues[$key]="${zero_file_issues[$key]},$hostname" fi elif [ "$file_count" -eq 1 ]; then if ! is_tree_whitelisted "$tree" && ! is_category_whitelisted "$tree" "$category"; then if [ -z "${one_file_issues[$key]}" ]; then one_file_issues[$key]="$hostname" else one_file_issues[$key]="${one_file_issues[$key]},$hostname" fi fi fi done done done # Write grouped alarms for 0 files for key in "${!zero_file_issues[@]}"; do tree="${key%%:*}" category="${key#*:}" sdp_list="${zero_file_issues[$key]}" sdp_count=$(echo "$sdp_list" | tr ',' '\n' | wc -l) if [ "$sdp_count" -eq 1 ]; then echo "[ALARM] $sdp_list - tree [$tree] category [$category] has 0 files" >> "$ALARM_FILE" elif [ "$sdp_count" -eq "$TOTAL_SDPS" ]; then echo "[ALARM] All $TOTAL_SDPS SDPs - tree [$tree] category [$category] has 0 files" >> "$ALARM_FILE" else echo "[ALARM] $sdp_count SDPs - tree [$tree] category [$category] has 0 files" >> "$ALARM_FILE" echo " Affected: $sdp_list" >> "$ALARM_FILE" fi done # Write grouped alarms for 1 file for key in "${!one_file_issues[@]}"; do tree="${key%%:*}" category="${key#*:}" sdp_list="${one_file_issues[$key]}" sdp_count=$(echo "$sdp_list" | tr ',' '\n' | wc -l) if [ "$sdp_count" -eq 1 ]; then echo "[ALARM] $sdp_list - tree [$tree] category [$category] has only 1 file" >> "$ALARM_FILE" elif [ "$sdp_count" -eq "$TOTAL_SDPS" ]; then echo "[ALARM] All $TOTAL_SDPS SDPs - tree [$tree] category [$category] has only 1 file" >> "$ALARM_FILE" else echo "[ALARM] $sdp_count SDPs - tree [$tree] category [$category] has only 1 file" >> "$ALARM_FILE" echo " Affected: $sdp_list" >> "$ALARM_FILE" fi done ################################# # CHECK CATEGORY CONSISTENCY (REFERENCE-BASED) ################################# echo "Checking category consistency..." # Group alarms by issue type declare -A extra_cat_sdps # tree:category -> list of SDPs with extra category declare -A missing_cat_sdps # tree:category -> list of SDPs missing category declare -A version_mismatch_sdps # tree:category -> list of "SDP:version" with mismatch for tree in $TREES; do # Get categories that REFERENCE has REF_CATEGORIES=$(grep "^FILE $tree .* REFERENCE$" "$FILE_DATA" | awk '{print $3}' | sort -u) # Get ALL categories across all SDPs ALL_CATEGORIES=$(grep "^FILE $tree " "$FILE_DATA" | awk '{print $3}' | sort -u) # Find categories that exist on other SDPs but NOT on reference for category in $ALL_CATEGORIES; do if ! echo "$REF_CATEGORIES" | grep -q "^${category}$"; then # This category is NOT in reference - find which SDPs have it key="${tree}:${category}" SDPS_WITH_CAT=$(grep "^FILE $tree $category " "$FILE_DATA" | grep -v " REFERENCE$" | awk '{print $5}' | sort -u | tr '\n' ',' | sed 's/,$//') extra_cat_sdps[$key]="$SDPS_WITH_CAT" fi done # Check for missing reference categories on other SDPs for category in $REF_CATEGORIES; do key="${tree}:${category}" for idx in "${!SDP_HOSTS[@]}"; do hostname="${SDP_HOSTS[$idx]}" [ "$hostname" = "$REFERENCE_SDP" ] && continue grep -q "^NODE $tree .* $hostname$" "$RAW_DATA" || continue if ! grep -q "^FILE $tree $category .* $hostname$" "$FILE_DATA"; then if [ -z "${missing_cat_sdps[$key]}" ]; then missing_cat_sdps[$key]="$hostname" else missing_cat_sdps[$key]="${missing_cat_sdps[$key]},$hostname" fi fi done done # Check version consistency WITHIN each category for category in $REF_CATEGORIES; do REF_FILE=$(grep "^FILE $tree $category .* REFERENCE$" "$FILE_DATA" | awk '{print $4}' | sort -r | head -1) [ -z "$REF_FILE" ] && continue key="${tree}:${category}" for idx in "${!SDP_HOSTS[@]}"; do hostname="${SDP_HOSTS[$idx]}" [ "$hostname" = "$REFERENCE_SDP" ] && continue grep -q "^FILE $tree $category .* $hostname$" "$FILE_DATA" || continue SDP_FILE=$(grep "^FILE $tree $category .* $hostname$" "$FILE_DATA" | awk '{print $4}' | sort -r | head -1) if [ -n "$SDP_FILE" ] && [ "$SDP_FILE" != "$REF_FILE" ]; then if [ -z "${version_mismatch_sdps[$key]}" ]; then version_mismatch_sdps[$key]="${hostname}:${SDP_FILE}" else version_mismatch_sdps[$key]="${version_mismatch_sdps[$key]},${hostname}:${SDP_FILE}" fi fi done done done # Write grouped alarms for extra categories for key in "${!extra_cat_sdps[@]}"; do tree="${key%%:*}" category="${key#*:}" sdp_list="${extra_cat_sdps[$key]}" sdp_count=$(echo "$sdp_list" | tr ',' '\n' | wc -l) if [ "$sdp_count" -eq 1 ]; then echo "[ALARM] $sdp_list - tree [$tree] has extra category [$category] not in reference (unique)" >> "$ALARM_FILE" elif [ "$sdp_count" -eq "$TOTAL_SDPS" ]; then echo "[ALARM] All $TOTAL_SDPS SDPs - tree [$tree] have extra category [$category] not in reference" >> "$ALARM_FILE" else echo "[ALARM] $sdp_count SDPs - tree [$tree] have extra category [$category] not in reference" >> "$ALARM_FILE" echo " Affected: $sdp_list" >> "$ALARM_FILE" fi done # Write grouped alarms for missing categories for key in "${!missing_cat_sdps[@]}"; do tree="${key%%:*}" category="${key#*:}" sdp_list="${missing_cat_sdps[$key]}" sdp_count=$(echo "$sdp_list" | tr ',' '\n' | wc -l) if [ "$sdp_count" -eq 1 ]; then echo "[ALARM] $sdp_list - tree [$tree] missing reference category [$category]" >> "$ALARM_FILE" elif [ "$sdp_count" -eq "$TOTAL_SDPS" ]; then echo "[ALARM] All $TOTAL_SDPS SDPs - tree [$tree] missing reference category [$category]" >> "$ALARM_FILE" else echo "[ALARM] $sdp_count SDPs - tree [$tree] missing reference category [$category]" >> "$ALARM_FILE" echo " Affected: $sdp_list" >> "$ALARM_FILE" fi done # Write grouped alarms for version mismatches for key in "${!version_mismatch_sdps[@]}"; do tree="${key%%:*}" category="${key#*:}" sdp_version_list="${version_mismatch_sdps[$key]}" sdp_count=$(echo "$sdp_version_list" | tr ',' '\n' | wc -l) REF_FILE=$(grep "^FILE $tree $category .* REFERENCE$" "$FILE_DATA" | awk '{print $4}' | sort -r | head -1) if [ "$sdp_count" -eq 1 ]; then sdp="${sdp_version_list%%:*}" node_ver="${sdp_version_list#*:}" echo "[ALARM] $sdp - tree [$tree] category [$category] version mismatch (ref=$REF_FILE, node=$node_ver)" >> "$ALARM_FILE" elif [ "$sdp_count" -eq "$TOTAL_SDPS" ]; then echo "[ALARM] All $TOTAL_SDPS SDPs - tree [$tree] category [$category] version mismatch (ref=$REF_FILE)" >> "$ALARM_FILE" echo "$sdp_version_list" | tr ',' '\n' | head -5 | while read sdp_ver; do sdp="${sdp_ver%%:*}" ver="${sdp_ver#*:}" echo " $sdp: $ver" >> "$ALARM_FILE" done if [ "$sdp_count" -gt 5 ]; then echo " ... and $((sdp_count - 5)) more SDPs" >> "$ALARM_FILE" fi else echo "[ALARM] $sdp_count SDPs - tree [$tree] category [$category] version mismatch (ref=$REF_FILE)" >> "$ALARM_FILE" echo "$sdp_version_list" | tr ',' '\n' | while read sdp_ver; do sdp="${sdp_ver%%:*}" ver="${sdp_ver#*:}" echo " $sdp: $ver" >> "$ALARM_FILE" done fi done ################################# # GENERATE STATISTICS ################################# echo "Generating statistics..." { echo "========================================" echo "ERE Monitoring Report - $TS" echo "========================================" echo "Reference: $REFERENCE_SDP" echo "Total SDPs: $TOTAL_SDPS" echo "Responding: $SUCCESSFUL" echo "Total Trees: $TREE_COUNT" echo "" echo "Whitelist Configuration:" echo " Trees (1 file allowed): ${IGNORE_SINGLE_FILE_TREES[*]:-none}" echo " Categories (1 file allowed): ${IGNORE_SINGLE_FILE_CATEGORIES[*]:-none}" echo "========================================" echo "" for tree in $TREES; do echo "----------------------------------------" echo "Tree: $tree" echo "----------------------------------------" SDP_COUNT=$(grep "^NODE $tree " "$RAW_DATA" | awk '{print $NF}' | sort -u | wc -l) REF_COUNT=$(grep "^REF $tree " "$RAW_DATA" | awk '{print $3}') echo "Found on SDPs: $SDP_COUNT / $TOTAL_SDPS" echo "Reference file count: $REF_COUNT" echo "" REF_CATEGORIES=$(grep "^FILE $tree .* REFERENCE$" "$FILE_DATA" | awk '{print $3}' | sort -u) ALL_CATEGORIES=$(grep "^FILE $tree " "$FILE_DATA" | awk '{print $3}' | sort -u) if [ -n "$ALL_CATEGORIES" ]; then echo "Categories found:" for cat in $ALL_CATEGORIES; do cat_count=$(grep "^FILE $tree $cat " "$FILE_DATA" | grep -v " REFERENCE$" | awk '{print $5}' | sort -u | wc -l) if echo "$REF_CATEGORIES" | grep -q "^${cat}$"; then ref_marker="[REF]" else ref_marker="[EXTRA]" fi # Check if whitelisted wl_marker="" if is_tree_whitelisted "$tree"; then wl_marker=" [WL-TREE]" elif is_category_whitelisted "$tree" "$cat"; then wl_marker=" [WL-CAT]" fi printf " %-20s %7s%10s : %2d / %2d SDPs" "$cat" "$ref_marker" "$wl_marker" "$cat_count" "$SDP_COUNT" if [ "$cat_count" -ne "$SDP_COUNT" ] && [ "$cat_count" -gt 0 ]; then SDPS_WITH=$(grep "^FILE $tree $cat " "$FILE_DATA" | grep -v " REFERENCE$" | awk '{print $5}' | sort -u | tr '\n' ',' | sed 's/,$//') echo " ($SDPS_WITH)" else echo "" fi done echo "" fi done TOTAL_ALARMS=$(grep -c '^\[ALARM\]' "$ALARM_FILE" 2>/dev/null || echo 0) echo "========================================" echo "Total Alarms: $TOTAL_ALARMS" echo "========================================" } > "$STATS_FILE" ################################# # SUMMARY ################################# TOTAL_ALARMS=$(grep -c '^\[ALARM\]' "$ALARM_FILE" 2>/dev/null || echo 0) echo "" echo "==========================================" echo "Complete!" echo "Alarms: $ALARM_FILE ($TOTAL_ALARMS alarms)" echo "Stats: $STATS_FILE" echo "==========================================" ################################# # GENERATE PRIORITIZED ALARM SMS ################################# SMS_ALARM_FILE="$HOME/ere_alarm.sms" > "$SMS_ALARM_FILE" if [ "$TOTAL_ALARMS" -gt 0 ]; then # Prioritize alarms by severity CRITICAL=$(grep "missing tree\|SSH failed" "$ALARM_FILE" | wc -l) HIGH=$(grep "extra category\|missing reference category" "$ALARM_FILE" | wc -l) MEDIUM=$(grep "version mismatch" "$ALARM_FILE" | wc -l) LOW=$(grep "has only 1 file\|has 0 files" "$ALARM_FILE" | wc -l) # Build severity summary SEVERITY="" [ "$CRITICAL" -gt 0 ] && SEVERITY="${SEVERITY}Critical:$CRITICAL " [ "$HIGH" -gt 0 ] && SEVERITY="${SEVERITY}ConfigMismatch:$HIGH " [ "$MEDIUM" -gt 0 ] && SEVERITY="${SEVERITY}VersionDiff:$MEDIUM " [ "$LOW" -gt 0 ] && SEVERITY="${SEVERITY}LowFiles:$LOW " # Collect top 5 issues TOP_ISSUES="" COUNTER=1 # Priority 1: Critical while read line; do [ "$COUNTER" -gt 5 ] && break if echo "$line" | grep -q "All [0-9]* SDPs"; then tree=$(echo "$line" | grep -o "tree \[[^]]*\]" | sed 's/tree \[\(.*\)\]/\1/' | head -c 15) TOP_ISSUES="${TOP_ISSUES}($COUNTER)ALL:$tree-missing " elif echo "$line" | grep -q "[0-9]* SDPs.*missing tree"; then count=$(echo "$line" | awk '{print $2}') tree=$(echo "$line" | grep -o "tree \[[^]]*\]" | sed 's/tree \[\(.*\)\]/\1/' | head -c 15) TOP_ISSUES="${TOP_ISSUES}($COUNTER)$count:$tree-missing " elif echo "$line" | grep -q "SSH failed"; then sdp=$(echo "$line" | awk '{print $2}') TOP_ISSUES="${TOP_ISSUES}($COUNTER)$sdp-unreachable " fi COUNTER=$((COUNTER + 1)) done < <(grep "missing tree\|SSH failed" "$ALARM_FILE" | head -3) # Priority 2: Config mismatch while read line; do [ "$COUNTER" -gt 5 ] && break if echo "$line" | grep -q "All [0-9]* SDPs"; then tree=$(echo "$line" | grep -o "tree \[[^]]*\]" | sed 's/tree \[\(.*\)\]/\1/' | head -c 12) cat=$(echo "$line" | grep -o "category \[[^]]*\]" | sed 's/category \[\(.*\)\]/\1/' | head -c 8) if echo "$line" | grep -q "extra"; then TOP_ISSUES="${TOP_ISSUES}($COUNTER)ALL:$tree-extra-$cat " else TOP_ISSUES="${TOP_ISSUES}($COUNTER)ALL:$tree-miss-$cat " fi elif echo "$line" | grep -q "[0-9]* SDPs"; then count=$(echo "$line" | awk '{print $2}') tree=$(echo "$line" | grep -o "tree \[[^]]*\]" | sed 's/tree \[\(.*\)\]/\1/' | head -c 12) cat=$(echo "$line" | grep -o "category \[[^]]*\]" | sed 's/category \[\(.*\)\]/\1/' | head -c 8) if echo "$line" | grep -q "extra"; then TOP_ISSUES="${TOP_ISSUES}($COUNTER)$count:$tree-extra-$cat " else TOP_ISSUES="${TOP_ISSUES}($COUNTER)$count:$tree-miss-$cat " fi fi COUNTER=$((COUNTER + 1)) done < <(grep "extra category\|missing reference category" "$ALARM_FILE" | head -$((6 - COUNTER))) # Priority 3: Version diff while read line; do [ "$COUNTER" -gt 5 ] && break if echo "$line" | grep -q "All [0-9]* SDPs"; then tree=$(echo "$line" | grep -o "tree \[[^]]*\]" | sed 's/tree \[\(.*\)\]/\1/' | head -c 12) cat=$(echo "$line" | grep -o "category \[[^]]*\]" | sed 's/category \[\(.*\)\]/\1/' | head -c 8) TOP_ISSUES="${TOP_ISSUES}($COUNTER)ALL:$tree-$cat-ver " elif echo "$line" | grep -q "[0-9]* SDPs"; then count=$(echo "$line" | awk '{print $2}') tree=$(echo "$line" | grep -o "tree \[[^]]*\]" | sed 's/tree \[\(.*\)\]/\1/' | head -c 12) cat=$(echo "$line" | grep -o "category \[[^]]*\]" | sed 's/category \[\(.*\)\]/\1/' | head -c 8) TOP_ISSUES="${TOP_ISSUES}($COUNTER)$count:$tree-$cat-ver " fi COUNTER=$((COUNTER + 1)) done < <(grep "version mismatch" "$ALARM_FILE" | head -$((6 - COUNTER))) # Priority 4: Low files while read line; do [ "$COUNTER" -gt 5 ] && break if echo "$line" | grep -q "All [0-9]* SDPs"; then tree=$(echo "$line" | grep -o "tree \[[^]]*\]" | sed 's/tree \[\(.*\)\]/\1/' | head -c 12) cat=$(echo "$line" | grep -o "category \[[^]]*\]" | sed 's/category \[\(.*\)\]/\1/' | head -c 8) if echo "$line" | grep -q "has 0 files"; then TOP_ISSUES="${TOP_ISSUES}($COUNTER)ALL:$tree-$cat-0file " else TOP_ISSUES="${TOP_ISSUES}($COUNTER)ALL:$tree-$cat-1file " fi elif echo "$line" | grep -q "[0-9]* SDPs"; then count=$(echo "$line" | awk '{print $2}') tree=$(echo "$line" | grep -o "tree \[[^]]*\]" | sed 's/tree \[\(.*\)\]/\1/' | head -c 12) cat=$(echo "$line" | grep -o "category \[[^]]*\]" | sed 's/category \[\(.*\)\]/\1/' | head -c 8) if echo "$line" | grep -q "has 0 files"; then TOP_ISSUES="${TOP_ISSUES}($COUNTER)$count:$tree-$cat-0file " else TOP_ISSUES="${TOP_ISSUES}($COUNTER)$count:$tree-$cat-1file " fi fi COUNTER=$((COUNTER + 1)) done < <(grep "has only 1 file\|has 0 files" "$ALARM_FILE" | head -$((6 - COUNTER))) # Build single-line SMS echo "Alarms:$TOTAL_ALARMS | ${SEVERITY}| Issues: ${TOP_ISSUES}| Details:~/ere_alarms_latest.txt" > "$SMS_ALARM_FILE" fi ################################# # SEND SMS NOTIFICATION ################################# if [ -f "/IN/HC/SDP/SMS/config/log4j2.xml" ]; then if [ "$TOTAL_ALARMS" -gt 0 ]; then echo "Sending SMS..." # Save current directory CURRENT_DIR=$(pwd) # Send SMS cd /IN/HC/SDP/SMS/ nohup java -Dlog4j.configurationFile=./config/log4j2.xml \ -classpath ".:./config:./libs/log4j-core-2.12.4.jar:./libs/log4j-api-2.12.4.jar:./libs/log4j-1.2-api-2.12.4.jar:./build/smpp.jar" \ com.etisalatmisr.notif.AlarmSender alrmx70 ~/user.dat "$SMS_ALARM_FILE" BCD-Alarm > /dev/null 2>&1 & # Return to original directory cd "$CURRENT_DIR" echo "SMS sent" else echo "No alarms - no SMS sent" fi fi ################################# # CLEANUP OLD FILES - KEEP ONLY LATEST ################################# # Move current files to fixed names (overwrite previous) if [ -f "$ALARM_FILE" ]; then cp "$ALARM_FILE" "$HOME/ere_alarms_latest.txt" fi if [ -f "$STATS_FILE" ]; then cp "$STATS_FILE" "$HOME/ere_stats_latest.txt" fi # Remove all timestamped files rm -f "$RAW_DATA" "$FILE_DATA" "$ALARM_FILE" "$STATS_FILE" echo "" echo "Latest reports:" echo " Alarms: $HOME/ere_alarms_latest.txt" echo " Stats: $HOME/ere_stats_latest.txt" if [ "$TOTAL_ALARMS" -gt 0 ]; then echo " SMS: $HOME/ere_alarm.sms" fi rm -f "$RAW_DATA" "$FILE_DATA" [ "$TOTAL_ALARMS" -gt 0 ] && exit 1 exit 0